function result = main(options)
%MAIN Complete measurement chain: ground speed from the Doppler echo of the road.
%   result = main() transmits a CW carrier from the antenna, scatters it off
%   the moving road, receives the echo and estimates the speed over the
%   road from the centroid of the echo spectrum. It plots the antenna
%   pattern, its footprint on the road and every stage of the waveform, and
%   prints a summary.
%
%   result = main(Name=Value) changes the set-up; the defaults are in
%   brackets.
%     CarrierFrequency - [Hz] (24.125e9), will be generated by the PLL.
%     MountHeight      - antenna height above the road [m] (0.5), check
%                        with the FS regulations.
%     Depression       - boresight angle below the horizon [deg] (45).
%     Yaw              - boresight azimuth from the direction of travel
%                        [deg] (180); 0, 90, 180, 270 = front, left, back,
%                        right.
%     Roll             - rotation about the boresight [deg] (0).
%     VehicleSpeed     - speed over the road [m/s] (20).
%     GammaDb          - ground reflectivity [dB] (-10).
%     TxPower          - transmit power [W] (10e-3).
%     SampleRate       - baseband sample rate [Hz] (20e3).
%     Duration         - observation time [s] (0.2).
%     Plot             - draw the figures (true).
%
%   result has the fields
%     Antenna, Ground               - the RadarAntenna and GroundPlane.
%     Transmitted, Radiated, Echo,  - the Waveform after every stage.
%     Received
%     DopplerCentroid               - power-weighted mean frequency of the
%                                     received echo [Hz].
%     BoresightDoppler              - Doppler shift of the boresight ground
%                                     point [Hz].
%     EstimatedSpeed                - speed over the road [m/s] from the
%                                     Doppler centroid.
%
%   Every call draws a new road; call rng(seed) first for a repeatable run.
arguments
    options.CarrierFrequency (1,1) double {mustBePositive, mustBeFinite} = 24.125e9
    options.MountHeight (1,1) double {mustBePositive, mustBeFinite} = 0.5
    options.Depression (1,1) double {mustBeInRange(options.Depression, -90, 90)} = 45
    options.Yaw (1,1) double {mustBeFinite} = 180
    options.Roll (1,1) double {mustBeFinite} = 0
    options.VehicleSpeed (1,1) double {mustBeFinite} = 20
    options.GammaDb (1,1) double {mustBeFinite} = -10
    options.TxPower (1,1) double {mustBePositive, mustBeFinite} = 10e-3
    options.SampleRate (1,1) double {mustBePositive, mustBeFinite} = 20e3
    options.Duration (1,1) double {mustBePositive, mustBeFinite} = 0.2
    options.Plot (1,1) logical = true
end

%% Antenna: 20 dBi Gaussian beam, 12 deg (azimuth) by 20 deg (elevation) wide
az = -180:1:180;        % Table azimuth grid [deg]
el = (-90:1:90).';      % Table elevation grid [deg]
gainDb = 20 - 10 * log10(2) * 4 * ((az / 12).^2 + (el / 20).^2);    % Gain table [dBi]
phaseDeg = zeros(size(gainDb));                                     % Phase table [deg]
ant = RadarAntenna(az, el, gainDb, phaseDeg, options.CarrierFrequency, ...
    options.Depression, options.Yaw, options.Roll);
if options.Plot
    ant.plotCuts(-90:0.1:90, 60);
    patternRange = 10;  % Dynamic range of the 3D pattern [dB]
    ant.plotPattern("vehicle", patternRange, MountHeight=options.MountHeight);   % Also draws the road footprint
end

%% Ground echo
% The waveform passes through the chain and every stage is kept for
% inspection. radiated has the samples of tx: the antenna pattern acts per
% direction, on transmit when the road scatters the wave and on receive.
fs = options.SampleRate;
ground = GroundPlane(options.GammaDb, -options.VehicleSpeed);  % The road moves backwards past the vehicle
tx = Waveform(sqrt(options.TxPower) * ones(round(options.Duration * fs), 1), fs, ...
    options.CarrierFrequency, Label="Transmitted CW");
radiated = ant.transmit(tx);
echo = ground.scatter(radiated, options.MountHeight);         % As an isotropic antenna would receive it
rx = ant.receive(echo);

%% Speed from the Doppler centroid
% The nearer, steeper part of the beam returns more power, which pulls the
% centroid below the boresight Doppler shift, so the estimate reads
% slightly low.
[P, f] = rx.spectrum();
centroid = sum(f .* P) / sum(P);
centre = ant.boresightGroundPoint(options.MountHeight);
boresightDoppler = ground.dopplerShift(ant, options.MountHeight, centre(1), centre(2));
b = ant.boresight();
estimatedSpeed = centroid * ant.Wavelength / (2 * b(1));
fprintf("Echo power %.1f dBm, Doppler centroid %.0f Hz (boresight %.0f Hz), estimated speed %.2f m/s\n", ...
    10 * log10(rx.Power / 1e-3), centroid, boresightDoppler, estimatedSpeed);

if options.Plot
    plot([tx, echo, rx], TimeLimits=[0 10e-3]);
    [ax, unit] = rx.plotSpectrum();
    xline(ax, boresightDoppler / unit, "--", "Boresight Doppler");
end

result = struct("Antenna", ant, "Ground", ground, ...
    "Transmitted", tx, "Radiated", radiated, "Echo", echo, "Received", rx, ...
    "DopplerCentroid", centroid, "BoresightDoppler", boresightDoppler, ...
    "EstimatedSpeed", estimatedSpeed);
end
